"""Verify command strings generated by the driver match the TDS2024C manual.

All tests use a mock VISA instrument so no hardware is required.
"""

import pytest
from unittest.mock import MagicMock, patch, call


def _make_osc(resource="USB0::0x0699::0x03A6::TEST::INSTR"):
    """Return a TDS2024C with a mocked VISA session."""
    from tektronix_tds2024c import TDS2024C
    osc = TDS2024C(resource)
    inst = MagicMock()
    inst.query.return_value = "0"
    inst.read_raw.return_value = b"#14\x00\x01\x02\x03"
    osc._inst = inst
    osc._rm   = MagicMock()
    return osc, inst


# ── Acquisition ────────────────────────────────────────────────────────────────

def test_acq_mode_sample():
    from tektronix_tds2024c import AcqMode
    osc, inst = _make_osc()
    osc.set_acq_mode(AcqMode.SAMPLE)
    inst.write.assert_called_with("ACQuire:MODe SAMple")


def test_acq_mode_average():
    from tektronix_tds2024c import AcqMode
    osc, inst = _make_osc()
    osc.set_acq_mode(AcqMode.AVERAGE)
    inst.write.assert_called_with("ACQuire:MODe AVErage")


def test_acq_numavg():
    osc, inst = _make_osc()
    osc.set_acq_numavg(16)
    inst.write.assert_called_with("ACQuire:NUMAVg 16")


def test_acq_single_sends_two_commands():
    osc, inst = _make_osc()
    osc.acq_single()
    calls = [c[0][0] for c in inst.write.call_args_list]
    assert "ACQuire:STOPAfter SEQuence" in calls
    assert "ACQuire:STATE RUN" in calls


def test_acq_stop():
    osc, inst = _make_osc()
    osc.acq_stop()
    inst.write.assert_called_with("ACQuire:STATE STOP")


