# ── capture_waveform with mocked binary transfer + positional WFMPre ────────────

def test_capture_waveform_binary_decodes_scaling():
    from tektronix_tds2024c import Channel, WfmEncoding
    osc, inst = _make_osc()
    # Realistic header-off positional WFMPre? response (16 fields)
    wfmpre = ('1;8;BIN;RI;MSB;5;"Ch1";Y;1.0E-9;0;0.0E0;"s";'
              '5.0E-1;0.0E0;0.0E0;"Volts"')
    inst.query.return_value = wfmpre
    import numpy as np
    inst.query_binary_values.return_value = np.array([0, 2, -2, 10, -10], dtype=np.int8)

    rec = osc.capture_waveform(Channel.CH1, encoding=WfmEncoding.RIBINARY, stop=5)

    # query_binary_values must be called with signed-byte, big-endian
    _, kwargs = inst.query_binary_values.call_args
    assert kwargs["datatype"] == "b"
    assert kwargs["is_big_endian"] is True
    # v = (adc - yoff) * ymult + yzero = adc * 0.5
    np.testing.assert_array_almost_equal(rec.v, [0.0, 1.0, -1.0, 5.0, -5.0])
    assert rec.dt == 1e-9
    assert rec.preamble.y_unit == "Volts"
